hreadID current = kNoThreadID;		MacGetCurrentThread(&current);		InsertLast(current);		// Start a watchdog timer		CThreadTimeout_AC timer(timeout);		// Wait until it's our turn, or we run out of time,		// or the queue is deleted. 		do		{			// Put ourselves to sleep			SetThreadStateEndCritical(kCurrentThreadID, kStoppedThreadState, fHolder);			// We're back, make sure we won't be interrupted			ThreadBeginCritical();			// If we woke up because the timer went off, give up			if (timer.Fired())			{				err = kMPTimeoutErr;				break;			}						// If the semaphore is gone, give up			if (fDeleted)			{				err = kMPDeletedErr;				break;			}		}		while (fHolder != current);		// Make really sure we're no longer in the queue. 		if (fHolder != current)			Delete(current);	}		ThreadEndCritical();	return err;}//----------------------------------------------------------------------------------------// End of CThreadWaitList_AC.cpp